import { Component, OnInit, AfterViewInit, ElementRef } from '@angular/core';

@Component({
  selector: 'app-effect-demo',
  template: `
    <div>
      <h2>Effect Demo</h2>
      <p>{{ message }}</p>
      <!-- Add paragraph to display counter value here -->
    </div>
  `,
  styleUrls: []
})
export class EffectDemoComponent implements OnInit, AfterViewInit {
  message: string = 'Initial message';
  counter: number = 0;

  constructor(private elementRef: ElementRef) {}

  ngOnInit() {
    this.message = 'Component initialized';
  }

  ngAfterViewInit() {
    const element = this.elementRef.nativeElement.querySelector('h2');
    if (element) {
      element.textContent = 'Effect Demo - View Initialized';
    }
  }

  incrementCounter() {
    this.counter++;
  }

  resetCounter() {
    this.counter = 0;
  }
}

